// ARCHIVO GENERADO - NO EDITAR A MANO.
// Se genera con: npm run build:invoice-assets
// Para cambiar el logo, la fuente o el diseño, edita los archivos de assets/
// y vuelve a ejecutar ese comando.
//
// Estos assets van incrustados (base64 / CSS en línea) para que el HTML de la
// cotización no dependa de ninguna descarga por red al generar el PDF.

'use strict';

const LOGO_DATA_URI = "data:image/png;base64,";

const FONT_FACE_CSS = "@font-face {\n  font-family: 'Inter';\n  font-style: normal;\n  font-weight: 400 700;\n  font-display: block;\n  src: url(data:font/woff2;base64,) format('woff2');\n}";

const INVOICE_CSS = "/* --- Fuente Inter ---\n   La fuente NO se importa por red. Se incrusta como @font-face con la fuente\n   en base64 al generar invoice-assets.js (ver scripts/build-invoice-assets.js).\n   Si se importara desde fonts.googleapis.com, el PDF se renderizaría antes de\n   que la fuente termine de descargar y saldría con la tipografía de respaldo. */\n\n/* --- Reset Básico y Configuración Global --- */\n*,\n*::before,\n*::after {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n}\n\nhtml {\n    font-size: 10pt;\n    line-height: 1.5;\n    background-color: #F6F8FC;\n    -webkit-print-color-adjust: exact;\n    color-adjust: exact;\n}\n\nbody {\n    font-family: 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    color: #5E6470;\n    background-color: #F9FAFC;\n    margin: 0 auto;\n    padding: 11mm 18mm 16mm 18mm; /* Aumentado a 18mm para separar del borde */\n    width: 210mm;\n    height: 297mm;\n    display: flex;\n    flex-direction: column;\n    box-sizing: border-box;\n}\n\n/* --- Títulos --- */\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n    font-weight: 600;\n    color: #1A1C21;\n    margin-bottom: 0;\n}\n\nh1 {\n    font-size: 28px;\n    line-height: 32px;\n    letter-spacing: -0.02em;\n    font-weight: 600;\n    text-transform: uppercase;\n}\n\np {\n    margin-bottom: 0;\n}\n\nstrong {\n    font-weight: 600;\n    color: #1A1C21;\n}\n\n/* --- Cabecera (Figma: y:32) --- */\n.header-section {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    height: 18mm;\n    /* 50px logo height equivalent */\n    margin-bottom: 11mm;\n    /* 30px equivalent to reach y:112 */\n}\n\n.invoice-title-block {\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n}\n\n.invoice-id {\n    font-size: 11px;\n    font-weight: 500;\n    letter-spacing: 0.03em;\n    text-transform: uppercase;\n    color: #5E6470;\n    line-height: 16px;\n}\n\n.logo {\n    height: 20mm;\n    /* Agrandado a 75px */\n    width: auto;\n    max-width: 45mm;\n    /* Agrandado a 170px */\n    object-fit: contain;\n}\n\n/* --- Rejilla de Información en 3 Columnas (Figma: y:112 a y:224) --- */\n.info-grid {\n    display: grid;\n    grid-template-columns: 1fr 1.1fr 1fr; /* Fluido para adaptarse a los márgenes */\n    border-top: 0.5px solid #D7DAE0;\n    border-bottom: 0.5px solid #D7DAE0;\n    height: 40mm;\n    /* 112px */\n    box-sizing: border-box;\n}\n\n.info-col {\n    padding: 18px 24px;\n    /* Cambiado a px para comportamiento estable en todos los navegadores */\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    /* 8px de separación interna */\n    box-sizing: border-box;\n    justify-content: flex-start;\n}\n\n.info-col:first-child {\n    padding-left: 0;\n}\n\n.info-col:last-child {\n    padding-right: 0;\n}\n\n.info-col:not(:last-child) {\n    border-right: 0.5px solid #D7DAE0;\n}\n\n.col-title {\n    font-size: 10px;\n    font-weight: 600;\n    color: #1A1C21;\n    line-height: 14px;\n    text-transform: uppercase;\n    letter-spacing: 0.03em;\n}\n\n.col-content {\n    font-size: 10px;\n    font-weight: 400;\n    line-height: 14px;\n    color: #5E6470;\n}\n\n.col-content strong {\n    font-size: 10px;\n    font-weight: 600;\n    color: #5E6470;\n}\n\n.client-vehicle-info {\n    margin-top: 6px;\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n    padding-left: 0;\n    /* Removido para alinear perfectamente con el nombre del cliente */\n    padding-right: 16px;\n    /* Empuja los valores hacia la izquierda para dar suficiente espacio */\n}\n\n.client-vehicle-info .info-row {\n    display: flex;\n    gap: 8px;\n    font-size: 9.5px;\n    line-height: 13px;\n}\n\n.client-vehicle-info .info-label {\n    font-weight: 600;\n    color: #1A1C21;\n    white-space: nowrap;\n}\n\n.client-vehicle-info .info-value {\n    color: #5E6470;\n}\n\n.client-detail {\n    margin-top: 4px;\n    font-size: 9.5px;\n    color: #5E6470;\n}\n\n/* --- Tabla de Ítems (Figma: table starts at y:264) --- */\n.invoice-items {\n    margin-top: 14mm;\n    /* 40px gap between grid bottom y:224 and table y:264 */\n    margin-bottom: 0;\n}\n\n.items-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 10px;\n}\n\n.items-table th {\n    color: #1A1C21;\n    font-weight: 600;\n    font-size: 10px;\n    line-height: 14px;\n    padding: 0 0 3mm 0;\n    text-align: left;\n    border-bottom: 0.5px solid #D7DAE0;\n}\n\n.items-table td {\n    padding: 2.2mm 0;\n    /* Compact padding to make sure 5 rows fit perfectly on A4 */\n    border-bottom: 0.5px solid #D7DAE0;\n    color: #5E6470;\n    vertical-align: middle;\n    font-size: 10px;\n    line-height: 14px;\n}\n\n.items-table .col-qty {\n    width: 14%;\n    /* 73px / 515px */\n    text-align: center;\n    font-weight: 500;\n}\n\n.items-table .col-desc {\n    width: 60%;\n    /* 307px / 515px */\n    font-weight: 600;\n    color: #1A1C21;\n}\n\n.items-table .col-price {\n    width: 16%;\n    /* 84px / 515px */\n    text-align: right;\n    font-weight: 500;\n}\n\n.items-table .col-total {\n    width: 10%;\n    /* 51px / 515px */\n    text-align: right;\n    font-weight: 500;\n}\n\n.summary-row {\n    display: flex;\n    justify-content: space-between;\n    font-size: 10px;\n    line-height: 14px;\n    padding: 3.5mm 0;\n    border-bottom: 0.5px solid #D7DAE0;\n}\n\n.summary-row .label {\n    color: #1A1C21;\n    font-weight: 600;\n}\n\n.summary-row .val {\n    font-weight: 500;\n    color: #5E6470;\n}\n\n.total-due-block {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    border-top: 1.5px solid #e4292c;\n    border-bottom: 1.5px solid #e4292c;\n    padding: 3.5mm 0;\n}\n\n.total-due-block .label {\n    font-size: 10px;\n    font-weight: 700;\n    color: #e4292c;\n    line-height: 14px;\n}\n\n.total-due-block .val {\n    font-size: 10px;\n    font-weight: 700;\n    color: #e4292c;\n    line-height: 14px;\n}\n\n/* --- Sección Inferior: Observaciones (Izq) y Totales (Der) --- */\n.bottom-section {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 14mm;\n    /* 40px gap */\n    margin-top: 6mm;\n    /* Subido cerca de la tabla según la foto */\n    margin-bottom: 0;\n}\n\n.bottom-left {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    gap: 6mm;\n    /* Espacio entre observaciones y métodos de pago */\n}\n\n.bottom-right {\n    width: 72mm;\n    /* 203px */\n    min-width: 72mm;\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n}\n\n.totals-box {\n    width: 100%;\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n}\n\n.terms-block {\n    font-size: 8px;\n    line-height: 12px;\n    color: #868DA6;\n}\n\n.terms-block h3 {\n    font-size: 8px;\n    font-weight: 600;\n    color: #868DA6;\n    margin-bottom: 2px;\n    text-transform: none;\n    letter-spacing: normal;\n}\n\n.terms-block p {\n    font-size: 8px;\n    line-height: 12px;\n    color: #868DA6;\n}\n\n/* --- Métodos de Pago --- */\n.payments-section {\n    margin-top: auto;\n    /* Empuja los métodos de pago, el agradecimiento y el footer al fondo */\n    margin-bottom: 0;\n}\n\n/* --- Mensaje (Figma: y:722) --- */\n.thanks-message {\n    margin-top: 6.4mm;\n    /* Distancia fija y compacta debajo de métodos de pago */\n    margin-bottom: 0;\n}\n\n.thanks-message h4 {\n    font-size: 10px;\n    font-weight: 600;\n    color: #1A1C21;\n    line-height: 14px;\n    margin-bottom: 4px;\n}\n\n.thanks-message p {\n    font-size: 10px;\n    color: #5E6470;\n    line-height: 14px;\n}\n\n/* --- Footer (Figma: y:796) --- */\n.footer-line {\n    border-top: 0.5px solid #D7DAE0;\n    padding-top: 4.2mm;\n    /* 12px */\n    margin-top: 11.3mm;\n    /* 32px gap below thanks-message y:764 */\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-size: 10px;\n    line-height: 14px;\n    color: #5E6470;\n    font-weight: 500;\n}\n\n.footer-line .separator {\n    color: #D7DAE0;\n    margin: 0 8px;\n}\n\n/* --- Estilos de Impresión --- */\n@media print {\n    html {\n        font-size: 9pt;\n        background-color: #ffffff;\n    }\n\n    body {\n        padding: 0;\n        box-shadow: none;\n        margin: 0;\n        max-width: 100%;\n        background-color: #ffffff;\n    }\n\n    .info-grid,\n    .info-col {\n        border-color: #D7DAE0 !important;\n    }\n\n    .items-table th,\n    .items-table td,\n    .footer-line {\n        border-color: #D7DAE0 !important;\n    }\n\n    .total-due-block {\n        border-color: #e4292c !important;\n        -webkit-print-color-adjust: exact;\n        color-adjust: exact;\n    }\n}\n\n@page {\n    margin: 0.4in;\n    size: A4;\n}\n";

module.exports = { LOGO_DATA_URI, FONT_FACE_CSS, INVOICE_CSS };
